"""Frozen exploratory conjunctions; no formal competence claim."""
def decision(comp,mechanism,integrity=True):
 screens={}
 for arm in ['D','T']:
  c=comp[arm+'-B'];m=mechanism[arm];adv=m['mean_matched_baseline_information_advantage_when_testing'];counts=m['counts']
  cond=dict(mean_information_per_probe_advantage_at_least_quarter_bit=c['mean_information_per_probe_advantage']>=.25-1e-12,median_paired_information_advantage_at_least1bit=c['median_paired_information_advantage_bits']>=1-1e-12,information_improved_at_least10worlds=c['information_wins']>=10,useful_contrast_advantage_at_least_half_per_world=c['useful_contrast_mean_advantage']>=.5,no_more_zero_information=c['zero_information_reduction']>=0,prediction_exact_regression_at_most1=c['short_exact_difference']>=-1,prediction_bit_regression_at_most2pp=c['short_bit_accuracy_difference']>=-.02-1e-12,prediction_testing_experiments_at_least16=m['prediction_testing_experiments']>=16,prediction_testing_worlds_at_least8=m['prediction_testing_worlds']>=8,prediction_linked_information_advantage_over_matched_B_at_least_quarter_bit=adv is not None and adv>=.25-1e-12,valid_analysis_fraction_at_least90pct=m['valid_analysis_fraction']>=.9,at_least12_valid_evidence_linked_comparisons=counts.get('valid_evidence_linked_comparisons',0)>=12,integrity=integrity)
  screens[arm+'-B']=dict(passed=all(cond.values()),conditions=cond)
 c=comp['T-D'];cond=dict(mean_information_per_probe_advantage_at_least_twelfth_bit=c['mean_information_per_probe_advantage']>=1/12-1e-12,median_paired_information_advantage_at_least_half_bit=c['median_paired_information_advantage_bits']>=.5-1e-12,information_improved_at_least10worlds=c['information_wins']>=10,useful_contrast_advantage_at_least_quarter_per_world=c['useful_contrast_mean_advantage']>=.25,no_more_zero_information=c['zero_information_reduction']>=0,prediction_exact_regression_at_most1=c['short_exact_difference']>=-1,prediction_bit_regression_at_most2pp=c['short_bit_accuracy_difference']>=-.02-1e-12,integrity=integrity)
 increment=dict(passed=all(cond.values()),conditions=cond);recommend='T' if screens['T-B']['passed'] and increment['passed'] else 'D' if screens['D-B']['passed'] else None
 return dict(screening=screens,triangulation_increment=increment,recommended_arm=recommend,recommend_scale_up=bool(recommend),classification='DELTA_PREDICTION_PILOT_SUPPORTS_CONFIRMATORY_PROPOSAL' if recommend else 'DELTA_PREDICTION_PILOT_NO_SCALE_UP',formal_competence_claim=False,larger_study_launched=False)
